def required_port(env, key, default=None):
    raw = env.get(key)
    if raw is None:
        if default is None:
            raise KeyError(f'{key} missing — set it before starting the app')
        return default
    try:
        port = int(raw)
    except ValueError:
        raise ValueError(f'{key}={raw!r} is not a number') from None
    if not 0 < port < 65536:
        raise ValueError(f'{key}={port} out of range 1-65535')
    return port

