def parse_rows(rows):
    records, skipped = [], []
    for row in rows:
        if ':' not in row:
            skipped.append((row, 'no separator'))
            continue
        name, raw_score = row.split(':', 1)
        name = name.strip()
        try:
            score = float(raw_score)
        except ValueError:
            skipped.append((row, 'score is not numeric'))
            continue
        if not name:
            skipped.append((row, 'empty name'))
            continue
        records.append((name, score))
    return records, skipped

