for name, score in records:
    print(f'{name:<8} {score:>6.1f}')
print('valid:', len(records), 'skipped:', len(skipped))
print('average:', round(sum(s for _, s in records) / len(records), 2))
for row, reason in skipped:
    print('  skip:', repr(row), '->', reason)

TRUE = {'true', '1', 'yes', 'y', 'on'}
FALSE = {'false', '0', 'no', 'n', 'off'}

def coerce(value, default):
    if value is None:
        return default
    target = type(default)
    if target is bool:
        if isinstance(value, str):
            token = value.strip().lower()
            if token in TRUE:
                return True
            if token in FALSE:
                return False
            return default
        return bool(value)
    try:
        return target(value)
    except (TypeError, ValueError):
        return default

