import copy

class Config:
    def __init__(self, payload=None):
        self._data = copy.deepcopy(payload or {})

    def _walk(self, path, create=False):
        parts = path.split('.')
        node = self._data
        for part in parts[:-1]:
            if part not in node:
                if not create:
                    return None, parts[-1]
                node[part] = {}
            if not isinstance(node[part], dict):
                raise TypeError(f'{part!r} is not a section')
            node = node[part]
        return node, parts[-1]

    def set(self, path, value):
        parent, key = self._walk(path, create=True)
        parent[key] = value
        return self

    def get(self, path, default=None):
        parent, key = self._walk(path)
        if parent is None or key not in parent:
            return default
        return parent[key]

    def apply_env(self, env, mapping):
        for env_key, path in mapping.items():
            if env_key in env:
                self.set(path, env[env_key])
        return self

