def update_path(data, path, value):
    key, *rest = path
    if not rest:
        return {**data, key: value}
    child = data.get(key)
    if not isinstance(child, dict):
        raise TypeError(f'{key!r} is not a nested mapping')
    return {**data, key: update_path(child, rest, value)}

original = {'db': {'host': 'h', 'port': 5432}, 'tags': ['a']}
updated = update_path(original, ['db', 'port'], 6543)

print('updated db.port :', updated['db']['port'])
print('original db.port:', original['db']['port'])
print('shared host key :', updated['db']['host'] is original['db']['host'])
print('shared tags     :', updated['tags'] is original['tags'])
print('new db section? :', updated['db'] is not original['db'])

try:
