TRUE = {'1', 'true', 'yes', 'on'}
FALSE = {'0', 'false', 'no', 'off'}

class ConfigError(ValueError):
    def __init__(self, key, value, expected):
        super().__init__(f'{key}={value!r} is not a valid {expected.__name__}')
        self.key, self.value, self.expected = key, value, expected

SCHEMA = {
    'host': (str, 'localhost'),
    'port': (int, 5432),
    'timeout': (float, 5.0),
    'debug': (bool, False),
    'workers': (int, 4),
}

def coerce(key, raw, target):
    if isinstance(raw, target) and target is not bool:
        return raw
    if target is bool:
        if isinstance(raw, str):
            token = raw.strip().lower()
            if token in TRUE:
                return True
            if token in FALSE:
                return False
            raise ConfigError(key, raw, bool)
        return bool(raw)
    try:
        return target(raw)
    except (TypeError, ValueError):
        raise ConfigError(key, raw, target) from None

def load(file_values=None, env=None, schema=None):
    schema = schema or SCHEMA
    file_values, env = file_values or {}, env or {}
    config, sources = {}, {}
    for key, (target, default) in schema.items():
        if key in env:
            raw, source = env[key], 'env'
        elif key in file_values:
            raw, source = file_values[key], 'file'
        else:
            raw, source = default, 'default'
        config[key] = coerce(key, raw, target)
        sources[key] = source
    return config, sources

file_cfg = {'port': '5432', 'debug': 'false', 'host': 'db.internal'}
env_cfg = {'DEBUG': '1'}
config, sources = load(file_cfg, {'debug': env_cfg['DEBUG']})

for key in sorted(config):
    print(f'{key:<8} = {config[key]!r:<12} ({sources[key]})')

print()
try:
    load({'port': 'not-a-port'})
except ConfigError as e:
    print('ConfigError:', e)
    print('  retry with 5432 instead?', e.key, e.expected.__name__, 'expected')

from decimal import Decimal
from collections import defaultdict
from dataclasses import dataclass, replace

@dataclass(frozen=True)
class Transaction:
    id: int
    date: str
    category: str
    amount: Decimal

    def validate(self):
        if self.amount <= 0:
            raise ValueError(f'{self.id}: amount must be positive')
        if len(self.date) != 10 or self.date[4] != '-' or self.date[7] != '-':
            raise ValueError(f'{self.id}: date must be YYYY-MM-DD')
        return self

class Store:
    def __init__(self, items=()):
        self._items = tuple(items)

    @property
    def items(self):
        return self._items

    def add(self, txn):
        return Store((*self._items, txn.validate()))

    def update(self, txn_id, **changes):
        new = tuple(
            replace(t, **changes).validate() if t.id == txn_id else t
            for t in self._items
        )
        if new == self._items:
            raise KeyError(f'no transaction {txn_id}')
        return Store(new)

    def total(self):
        return sum((t.amount for t in self._items), Decimal('0'))

    def by_category(self):
        out = defaultdict(lambda: Decimal('0'))
        for t in self._items:
            out[t.category] += t.amount
        return dict(sorted(out.items(), key=lambda kv: kv[1], reverse=True))

    def by_month(self):
        out = defaultdict(lambda: Decimal('0'))
        for t in self._items:
            out[t.date[:7]] += t.amount
        return dict(sorted(out.items()))

store = Store()
store = store.add(Transaction(1, '2026-08-03', 'food', Decimal('450.50')))
store = store.add(Transaction(2, '2026-08-11', 'travel', Decimal('1200')))
store = store.add(Transaction(3, '2026-09-02', 'food', Decimal('399.50')))
store = store.add(Transaction(4, '2026-09-14', 'books', Decimal('850')))

before = store
store = store.update(3, amount=Decimal('359.50'))

print('total (new)   :', store.total())
print('total (before):', before.total())
print('items shared  :', before.items[0] is store.items[0])
print('by category   :', {k: str(v) for k, v in store.by_category().items()})
print('by month      :', {k: str(v) for k, v in store.by_month().items()})
